    let (name, config_m) = m.subcommand().unwrap();
    assert_eq!(name, "config");
    let (name, set_m) = config_m.subcommand().unwrap();
    assert_eq!(name, "set");
    assert_eq!(
        set_m.get_one::<String>("key").map(String::as_str),
